/**
* Giải mã mảng JSON 2 chiều từ hệ thống trộn đề QM2025 sang cấu trúc AnswerKeyData
* Hỗ trợ tự động tương thích với toàn bộ 14 mẫu phiếu (cả mã đề 3 chữ số và 4 chữ số)
*/
function parseQM2025QrPayload(rawText, templateId = "qm_khtn_dia") {
	const cleaned = rawText.trim();
	const parsed = JSON.parse(cleaned);
	if (!Array.isArray(parsed)) throw new Error("Dữ liệu QR không phải mảng JSON hợp lệ.");
	const rows = Array.isArray(parsed[0]) ? parsed : [parsed];
	const tpl = TEMPLATES[templateId] || TEMPLATES.qm_khtn_dia;
	const result = [];
	for (const row of rows) {
		if (!Array.isArray(row) || row.length < 2) continue;
		let examCode = String(row[0]).trim();
		if (tpl.maDeDigits === 4 && examCode.length === 3) examCode = examCode.padStart(4, "0");
		else if (tpl.maDeDigits === 3 && examCode.length === 4 && examCode.startsWith("0")) examCode = examCode.slice(1);
		if (row.length === 41) {
			const p1Full = row.slice(1, 19).map((v) => String(v).toUpperCase().trim());
			const choices = [
				"A",
				"B",
				"C",
				"D"
			];
			const p1 = [];
			for (let i = 0; i < Math.max(tpl.p1Count, 40); i++) p1.push(p1Full[i] || choices[i % 4]);
			const p2Raw = row.slice(19, 35).map((v) => {
				const s = String(v).toUpperCase().trim();
				return s === "Đ" || s === "D" || s === "TRUE" || s === "1" ? "D" : "S";
			});
			const p2 = [];
			for (let q = 0; q < Math.max(tpl.p2Count, 16); q++) p2.push({
				a: p2Raw[q % 4 * 4] || "D",
				b: p2Raw[q % 4 * 4 + 1] || "D",
				c: p2Raw[q % 4 * 4 + 2] || "D",
				d: p2Raw[q % 4 * 4 + 3] || "D"
			});
			const p3Base = row.slice(35, 41).map((v) => v);
			const p3 = [];
			for (let i = 0; i < Math.max(tpl.p3Count, 12); i++) p3.push(p3Base[i % p3Base.length] ?? 16);
			result.push({
				examCode,
				p1,
				p2,
				p3
			});
		} else {
			const p1Count = Math.max(tpl.p1Count, 40);
			const p2Count = Math.max(tpl.p2Count, 16);
			const p3Count = Math.max(tpl.p3Count, 12);
			const choices = [
				"A",
				"B",
				"C",
				"D"
			];
			const p1 = [];
			for (let i = 0; i < p1Count; i++) {
				const val = row[1 + i];
				const s = val !== void 0 ? String(val).toUpperCase().trim() : "";
				p1.push(choices.includes(s) ? s : choices[i % 4]);
			}
			const p2 = [];
			for (let q = 0; q < p2Count; q++) {
				const base = 1 + Math.min(row.length - 1, 18) + q % 4 * 4;
				const normDS = (v) => {
					const s = String(v ?? "D").toUpperCase().trim();
					return s === "Đ" || s === "D" || s === "TRUE" || s === "1" ? "D" : "S";
				};
				p2.push({
					a: normDS(row[base]),
					b: normDS(row[base + 1]),
					c: normDS(row[base + 2]),
					d: normDS(row[base + 3])
				});
			}
			const p3 = [];
			for (let i = 0; i < p3Count; i++) {
				const val = row[1 + tpl.p1Count + tpl.p2Count * 4 + i];
				p3.push(val !== void 0 ? val : 16);
			}
			result.push({
				examCode,
				p1,
				p2,
				p3
			});
		}
	}
	return result;
}
